// BINARY REPRESENTATION OPERATIONS

// Convert decimal to binary string
function toBinary(n) {
    if (n === 0) return '0';
    let result = '';
    while (n > 0) {
        result = (n & 1) + result; // LSB first, then prepend
        n >>= 1;                   // right shift by 1 = divide by 2
    }
    return result;
}

// Built-in: n.toString(2) for unsigned, handles negatives as '-' + abs
console.log((13).toString(2));   // '1101'
console.log((255).toString(2));  // '11111111'
console.log(toBinary(13));       // '1101'

// COMMON BIT PATTERNS:
const patterns = {
    allOnes32:    0xFFFFFFFF, // -1 in two's complement (32-bit)
    maxPositive:  0x7FFFFFFF, // 2147483647 = 2^31 - 1
    minNegative:  0x80000000, // -2147483648 = -2^31
    isPowerOf2:   n => n > 0 && (n & (n-1)) === 0, // exactly one bit set
    lowestSetBit: n => n & (-n),                    // isolate rightmost 1
    clearLowest:  n => n & (n-1),                   // clear rightmost 1 bit
    countBits:    n => n.toString(2).split('').filter(b => b==='1').length
};

console.log(patterns.isPowerOf2(8));    // true  (1000: one bit)
console.log(patterns.isPowerOf2(6));    // false (110: two bits)
console.log(patterns.lowestSetBit(12)); // 4     (1100 -> 0100)
console.log(patterns.clearLowest(12));  // 8     (1100 -> 1000)

// TWO'S COMPLEMENT
console.log(~5 + 1);  // -5  (invert 0101 -> 1010, add 1 -> 1011 = -5 in 32-bit)
console.log(-5 >>> 0); // 4294967291 (unsigned 32-bit view of -5)
// -5 in 32-bit two's complement = 0xFFFFFFFB = 4294967291

