// CANONICAL BIT OPERATION PATTERNS

// CHECK: is bit k set in n?
function isBitSet(n, k)    { return (n >> k) & 1; }  // shift bit k to position 0, check
// Alternative: return (n & (1 << k)) !== 0;

// SET: set bit k in n
function setBit(n, k)      { return n | (1 << k); }    // OR with mask

// CLEAR: clear bit k in n
function clearBit(n, k)    { return n & ~(1 << k); }   // AND with inverted mask

// TOGGLE: flip bit k in n
function toggleBit(n, k)   { return n ^ (1 << k); }    // XOR with mask

// EXTRACT: get value of bits [lo..hi] in n
function extractBits(n, lo, hi) {
    const mask = ((1 << (hi - lo + 1)) - 1) << lo;
    return (n & mask) >> lo;
}

console.log(isBitSet(13, 2)); // 1 (13=1101, bit 2 = 1)
console.log(isBitSet(13, 1)); // 0 (13=1101, bit 1 = 0)
console.log(setBit(8, 1));    // 10 (1000 | 0010 = 1010)
console.log(clearBit(13, 2)); // 9  (1101 & ~0100 = 1101 & 1011 = 1001)
console.log(toggleBit(13, 2)); // 9 (1101 ^ 0100 = 1001)

// XOR TRICKS:
// Single Number (#136): find the one element that appears once, all others appear twice
function singleNumber(nums) {
    return nums.reduce((acc, n) => acc ^ n, 0);
    // XOR all: duplicates cancel (a^a=0), unique element remains (0^a=a)
}
console.log(singleNumber([4,1,2,1,2])); // 4

// Swap without temp variable (using XOR)
function swapXOR(arr, i, j) {
    arr[i] ^= arr[j]; // a = a^b
    arr[j] ^= arr[i]; // b = b^(a^b) = a
    arr[i] ^= arr[j]; // a = (a^b)^a = b
    // Warning: if i==j, this sets arr[i] to 0! Check i!==j first.
}

// SHIFT OPERATIONS:
console.log(1 << 3);   // 8  (left shift 3 = multiply by 8)
console.log(16 >> 2);  // 4  (right shift 2 = divide by 4)
console.log(-4 >> 1);  // -2 (arithmetic: fills with sign bit 1)
console.log(-4 >>> 1); // 2147483646 (logical: fills with 0)

