// NUMBER OF 1 BITS (#191)

// NAIVE: check all 32 bits O(32)
function hammingWeight_naive(n) {
    let count = 0;
    for (let i = 0; i < 32; i++) {
        if (n & 1) count++;
        n >>>= 1; // unsigned right shift: fills with 0, handles negative inputs
    }
    return count;
}

// BRIAN KERNIGHAN'S: O(k) where k = number of set bits
function hammingWeight(n) {
    let count = 0;
    while (n !== 0) {
        n &= (n - 1); // clear the lowest set bit
        count++;
    }
    return count;
}

console.log(hammingWeight(11));         // 3  (1011: three 1s)
console.log(hammingWeight(128));        // 1  (10000000: one 1)
console.log(hammingWeight(0xFFFFFFFF)); // 32 (all 1s)

// WHY n & (n-1) CLEARS THE LOWEST SET BIT:
// n = ...a1000...0 (lowest set bit at position k)
// n-1 = ...a0111...1 (borrow propagates through the 0s)
// n & (n-1) = ...a0000...0 (bit k cleared, bits 0..k-1 cleared)
// All bits above k are unchanged.

// TRACE for n=12 (1100):
// n=12=1100: n&(n-1) = 1100 & 1011 = 1000 = 8. count=1.
// n=8=1000:  n&(n-1) = 1000 & 0111 = 0000 = 0. count=2.
// n=0: loop ends. Return 2. ✓ (1100 has two set bits)

// HAMMING DISTANCE (#461) — extension of bit counting
function hammingDistance(x, y) {
    return hammingWeight(x ^ y); // XOR gives differing bits; count them
}
console.log(hammingDistance(1, 4)); // 2  (001 XOR 100 = 101, two 1s)

// TOTAL HAMMING DISTANCE (#477) — sum over all pairs
function totalHammingDistance(nums) {
    let total = 0;
    for (let bit = 0; bit < 32; bit++) {
        const ones = nums.filter(n => (n >> bit) & 1).length;
        const zeros = nums.length - ones;
        total += ones * zeros; // each 1-0 pair contributes 1 to distance
    }
    return total;
}

