// COUNTING BITS (#338)

// NAIVE: O(n * 32)
function countBits_naive(n) {
    return Array.from({length: n+1}, (_, i) => hammingWeight(i));
}

// DP APPROACH 1: dp[i] = dp[i>>1] + (i&1)  O(n)
function countBits(n) {
    const dp = new Array(n + 1).fill(0); // dp[0] = 0
    for (let i = 1; i <= n; i++) {
        dp[i] = dp[i >> 1] + (i & 1);
        // dp[i>>1]: popcount of i without its lowest bit
        // (i & 1): the lowest bit itself (0 or 1)
    }
    return dp;
}

// DP APPROACH 2: dp[i] = dp[i & (i-1)] + 1  O(n)
function countBits_v2(n) {
    const dp = new Array(n + 1).fill(0);
    for (let i = 1; i <= n; i++) {
        dp[i] = dp[i & (i-1)] + 1;
        // i & (i-1): clear lowest set bit
        // dp[i&(i-1)]: popcount one less than i's
    }
    return dp;
}

console.log(countBits(5));   // [0,1,1,2,1,2]
console.log(countBits_v2(5));// [0,1,1,2,1,2]

// TRACE for n=5:
// dp[0]=0 (base)
// dp[1]: dp[0]+1=1.  (1>>1=0, 1&1=1. dp[0]+1=1)
// dp[2]: dp[1]+0=1.  (2>>1=1, 2&1=0. dp[1]+0=1)
// dp[3]: dp[1]+1=2.  (3>>1=1, 3&1=1. dp[1]+1=2)
// dp[4]: dp[2]+0=1.  (4>>1=2, 4&1=0. dp[2]+0=1)
// dp[5]: dp[2]+1=2.  (5>>1=2, 5&1=1. dp[2]+1=2)
// Result: [0,1,1,2,1,2] ✓

// PATTERN: dp[2k] = dp[k] (even numbers have same bits as their half)
//          dp[2k+1] = dp[k] + 1 (odd numbers add 1 to their half)
console.log('Even pattern: dp[8]=', countBits(8)[8]);  // 1 = dp[4] = 1
console.log('Odd pattern: dp[9]=',  countBits(9)[9]);  // 2 = dp[4]+1 = 2

