// REVERSE BITS (#190)
// O(32) time, O(1) space
function reverseBits(n) {
    let result = 0;
    for (let i = 0; i < 32; i++) {
        result <<= 1;        // make room: shift result left by 1
        result |= (n & 1);   // insert LSB of n as new LSB of result
        n >>>= 1;            // unsigned right shift: move to next bit of n
    }
    return result >>> 0;     // ensure unsigned 32-bit result in JavaScript
}

// Explanation:
// Each iteration: result = (result << 1) | (n & 1); n >>>=1;
// Effectively: reads n from LSB to MSB and writes into result from LSB to MSB
// This reverses the bit order

console.log(reverseBits(0b00000010100101000001111010011100).toString(2));
// Input:  00000010100101000001111010011100 = 43261596
// Output: 00111001011110000010100101000000 = 964176192
console.log(reverseBits(43261596)); // 964176192

// TRACE for n=11 (0000...01011), 32-bit:
// Only showing last 5 bits for clarity:
// i=0: result=0, n&1=1: result=1(0001). n>>>=1: n=5(0101).
// i=1: result=2(0010), n&1=1: result=3(0011). n>>>=1: n=2(0010).
// i=2: result=6(0110), n&1=0: result=6(0110). n>>>=1: n=1(0001).
// i=3: result=12(1100), n&1=1: result=13(1101). n>>>=1: n=0.
// i=4..31: n=0, n&1=0: result just shifts left each time.
// Final: 13 << 28 = 0xD0000000 (in full 32-bit)
// 11 = 0b...01011 reversed = 0b11010... (the 5 bits reversed in 32-bit position)

// DIVIDE AND CONQUER: swap halves, quarters, pairs, bits
function reverseBits_opt(n) {
    n = ((n & 0xFFFF0000) >>> 16) | ((n & 0x0000FFFF) << 16); // swap 16-bit halves
    n = ((n & 0xFF00FF00) >>> 8)  | ((n & 0x00FF00FF) << 8);  // swap 8-bit quarters
    n = ((n & 0xF0F0F0F0) >>> 4)  | ((n & 0x0F0F0F0F) << 4);  // swap 4-bit nibbles
    n = ((n & 0xCCCCCCCC) >>> 2)  | ((n & 0x33333333) << 2);  // swap 2-bit pairs
    n = ((n & 0xAAAAAAAA) >>> 1)  | ((n & 0x55555555) << 1);  // swap individual bits
    return n >>> 0;
}

