// SUM OF TWO INTEGERS WITHOUT + OR - (#371)
// O(number of carry propagations) time, O(1) space
function getSum(a, b) {
    // Mask to 32 bits to handle JavaScript's sign extension
    const MASK = 0xFFFFFFFF;
    const MAX  = 0x7FFFFFFF;

    while (b !== 0) {
        const carry = ((a & b) << 1) & MASK; // carries, masked to 32 bits
        a = (a ^ b) & MASK;                   // sum without carry, masked
        b = carry;
    }

    // Convert from unsigned 32-bit to signed if necessary
    return a <= MAX ? a : ~(a ^ MASK);
    // If a > MAX: it represents a negative number in two's complement
    // ~(a ^ MASK) = ~(a ^ 0xFFFFFFFF) inverts the masking to get the negative value
}

console.log(getSum(1, 2));    // 3
console.log(getSum(-2, 3));   // 1
console.log(getSum(-1, -1));  // -2
console.log(getSum(7, 0));    // 7

// TRACE for a=5 (0101), b=3 (0011):
// Iteration 1:
//   a&b = 0101 & 0011 = 0001. carry = 0001<<1 = 0010.
//   a^b = 0101 ^ 0011 = 0110.
//   a=0110(6), b=0010.
// Iteration 2:
//   a&b = 0110 & 0010 = 0010. carry = 0010<<1 = 0100.
//   a^b = 0110 ^ 0010 = 0100.
//   a=0100(4), b=0100.
// Iteration 3:
//   a&b = 0100 & 0100 = 0100. carry = 0100<<1 = 1000.
//   a^b = 0100 ^ 0100 = 0000.
//   a=0000(0), b=1000.
// Iteration 4:
//   a&b = 0000 & 1000 = 0000. carry = 0.
//   a^b = 0000 ^ 1000 = 1000.
//   a=1000(8), b=0.
// b=0: loop ends. a=8. ✓  (5+3=8)

// WITHOUT THE MASK (naive, fails for negatives in JavaScript):
